','d7f7c80f-fd7b-4d68-a050-5106e2aa2c81','d9a9f4e4-3772-482b-806b-e23b781af1b3','da1688ad-3391-489f-a2fe-f43d1f01529f','da2322b6-6562-42bb-859f-5bb832be2605','dabe081d-b046-4516-8117-f96ed35a686d','db16dfb5-0695-4e18-9a54-c65db9593728','db46d8f2-cea3-4246-a185-c04f548b34ba','decaa19e-7914-40f0-a50e-2a3a8cd8cbae','dedc48f3-cb65-40c3-9c3d-55c787980953','e01d553f-d42d-4e65-bbcc-f5d93cbdb8e4','e2c1ec60-a291-42e5-b6ac-8c1cb47a6ecd','e3eab657-0410-4f85-81dd-925fad290d7d','e3fce365-9159-4b60-bea1-82a0aea154df','e43c6f14-e150-4352-9167-a9aa705f5a6d','e6586fa7-c87e-4252-b74f-9e62f80fca87','e902caed-8e8b-4f07-a2cb-79a2a60acca7','e9ed58d3-fc83-4888-95f4-d926a537b38a','eba00c24-13ae-4dee-b006-92b491004b10','ec8cea1a-721b-4611-8f35-c0df21f2b1e2','ecbd2bfd-4014-4558-bf73-95434e692ed0','ecfd3d04-f8ed-48a4-b0fc-18fed1f6bc11','ee123b84-745b-4761-8dfb-9d93286a3635','ee92e64b-c0eb-4a6a-8e33-67b7bb004d03','ef32164b-eee6-432f-aa73-c42fbb98377c','f0e2105a-c4b0-4560-bb88-3e27617a0eac','f230905c-0c3d-473e-ab5a-71155616cfa8','f263719d-66f2-4232-889c-f1f5412888fc','f2949768-184b-46f3-bf46-791a412a97f5','f45e982f-d9ed-4e5b-930b-47dceefc62e1','f4e7c891-2bef-4d08-840f-47c69a148614','f5110469-6656-48ad-8442-7b22f8b91a22','f5c1fa74-3f94-4603-ac2e-d74c07ddf4f4','f6b41768-aacc-490a-a334-17f87d753e1e','f99b074f-3112-4ec9-ac3e-b6253b55d1cb','fd288f7d-5a6b-41ae-8d8e-d34ccc19cee9','fe9bc28d-2e0a-4f3d-bacd-4cbf48ecd5e4','ffb5c874-8d0e-4d62-943d-c49f1b0c2646']::uuid[];
  v_count integer;
  v_amount numeric;
  v_id uuid;
  v_value numeric;
  v_r jsonb;
  v_n integer:=0;
  v_sum numeric:=0;
  v_ids uuid[]:=ARRAY[]::uuid[];
BEGIN
  IF to_regprocedure('public.fn_ca_pay_closed_target_ticket_in_cash(uuid,text)') IS NULL THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_DOOR_MISSING: apply 20261012054804 first';
  END IF;
  SELECT count(*), COALESCE(sum(tk.value),0) INTO v_count,v_amount
    FROM public.tournament_tickets tk WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-22 08:00:00+00' AND tk.created_at<'2026-09-24 17:45:30+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id);
  IF v_count<>190 OR v_amount<>7500.00 THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_PREIMAGE_CHANGED: part 4 has % tickets worth %',v_count,v_amount;
  END IF;
  FOR v_id,v_value IN
    SELECT tk.id,tk.value FROM public.tournament_tickets tk
     WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-22 08:00:00+00' AND tk.created_at<'2026-09-24 17:45:30+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id)
     ORDER BY tk.created_at,tk.id
  LOOP
    v_r:=public.fn_ca_pay_closed_target_ticket_in_cash(v_id,'stranded_ticket_settlement_20261012');
    IF COALESCE((v_r->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_r->>'replayed')::boolean,false)
       OR (v_r->>'amount')::numeric IS DISTINCT FROM v_value THEN
      RAISE EXCEPTION 'STRANDED_TICKET_CASH_REFUSED: %',v_r;
    END IF;
    v_n:=v_n+1;
    v_sum:=round(v_sum+v_value,2);
    v_ids:=v_ids||v_id;
  END LOOP;
  IF v_n<>190 OR v_sum<>7500.00 THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_RESULT_CHANGED: paid % tickets worth %',v_n,v_sum;
  END IF;
  IF (SELECT count(*) FROM public.tournament_tickets tk
       WHERE tk.id=ANY(v_ids) AND tk.status='redeemed'
         AND tk.redeemed_at=transaction_timestamp())<>v_n
     OR (SELECT COALESCE(sum(l.amount),0)
           FROM public.chip_ledger_idem i JOIN public.chip_ledger l ON l.id=i.leg_id
          WHERE i.idempotency_key IN (
            SELECT 'ticket:'||x::text||':closed-target-cash' FROM unnest(v_ids) x)
            AND l.from_type='escrow' AND l.to_type='player_wallet'
            AND l.category='ticket_redeem')<>v_sum
     OR EXISTS (SELECT 1 FROM public.tournament_tickets tk WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-22 08:00:00+00' AND tk.created_at<'2026-09-24 17:45:30+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id)) THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_RESULT_CHANGED: receipts disagree for % tickets worth %',v_n,v_sum;
  END IF;
  RAISE NOTICE 'stranded satellite tickets paid in cash, part 4: % tickets worth %',v_n,v_sum;
END
$settle$;
COMMIT;
